522	                log.error("[SkipRead] 배송 정보 읽기 스킵: 사유={}", t.getMessage(), t);
523	            }
524	
525	            @Override
526	            public void onSkipInWrite(OrderShipment item, Throwable t) {
527	                if (item != null) {
528	                    log.error("[SkipWrite] 배송 상태 저장 스킵: shipmentId={}, trackingNumber={}, status={}, 사유={}",
529	                            item.getId(),
530	                            item.getTrackingNumber(),
531	                            item.getStatus(),
532	                            t.getMessage(),
533	                            t);
534	                } else {
535	                    log.error("[SkipWrite] 배송 상태 저장 스킵: item=null, 사유={}", t.getMessage(), t);
