475	     * 배송사 상태 텍스트를 내부 ShipmentStatus로 매핑합니다.
476	     *
477	     * @param statusText 배송사 상태 텍스트
478	     * @return 매핑된 ShipmentStatus
479	     */
480	    private ShipmentStatus mapToShipmentStatus(String statusText) {
481	        return switch (statusText) {
482	            case "배송완료" -> ShipmentStatus.DELIVERED;
483	            case "배송출발" -> ShipmentStatus.OUT_FOR_DELIVERY;
484	            default -> ShipmentStatus.IN_TRANSIT;
485	        };
486	    }
