   312	public enum SaleStatus {
   313	    PENDING_SHIPMENT,    // 판매자 발송 대기
   314	    IN_TRANSIT,          // 배송 중
   315	    IN_INSPECTION,       // 검수 중
   316	    FAILED_INSPECTION,   // 검수 불합격
   317	    IN_STORAGE,          // 창고 보관 중
   318	    ON_AUCTION,          // 판매 입찰 중
   319	    SELLING,             // 판매중 (등록된 상태)
   320	    SOLD,                // 판매 완료
   321	    AUCTION_EXPIRED;     // 입찰 기한 만료
   322	
   323	    // 상태 전환 규칙
   324	    public boolean canTransitionTo(SaleStatus newStatus) {
   325	        return switch (this) {
   326	            case PENDING_SHIPMENT -> newStatus == IN_TRANSIT;
   327	            case IN_TRANSIT -> newStatus == IN_INSPECTION;
   328	            case IN_INSPECTION -> newStatus == FAILED_INSPECTION || newStatus == IN_STORAGE;
   329	            case IN_STORAGE -> newStatus == ON_AUCTION || newStatus == AUCTION_EXPIRED || newStatus == SELLING;
   330	            case ON_AUCTION -> newStatus == SOLD || newStatus == AUCTION_EXPIRED;
   331	            case SELLING -> newStatus == SOLD || newStatus == AUCTION_EXPIRED || newStatus == ON_AUCTION;
   332	            case SOLD, AUCTION_EXPIRED, FAILED_INSPECTION -> false; // SOLD 상태에서는 다른 상태로 전환 불가
   333	        };
   334	    }
