    33	    public String getCurrentTrackingStatus(String trackingNumber) throws Exception {
    34	        if (trackingNumber == null || trackingNumber.isBlank()) {
    35	            log.warn("유효하지 않은 운송장 번호: {}", trackingNumber);
    36	            throw new ShipmentException(ShipmentErrorCode.TRACKING_NUMBER_INVALID);
    37	        }
    38	
    39	        log.info("CJ대한통운 배송 상태 조회 시작: 운송장 번호 = {}", trackingNumber);
    40	
    41	        Playwright playwright = null;
    42	        Browser browser = null;
    43	        Page page = null;
    44	
    45	        try {
    46	            // 1) Playwright 객체 생성
    47	            log.debug("Playwright 인스턴스 생성");
    48	            playwright = Playwright.create();
    49	
    50	            // 2) Chromium 브라우저를 headless 모드로 실행
    51	            log.debug("Chromium 브라우저 시작 (headless 모드)");
    52	            browser = playwright.chromium().launch(
    53	                    new BrowserType.LaunchOptions()
    54	                            .setHeadless(true)
    55	                            .setSlowMo(100)
    56	            );
    57	
    58	            page = browser.newPage();
    59	
    60	            // 3) 해당 URL로 이동
    61	            String url = TRACKING_URL_PREFIX + trackingNumber;
    62	            log.debug("배송 조회 페이지로 이동: {}", url);
    63	            page.navigate(url);
    64	
    65	            // 4) 자바스크립트로 tbody#statusDetail이 채워질 때까지 대기
    66	            log.debug("배송 상태 테이블 로드 대기 (최대 {}ms)", SELECTOR_TIMEOUT_MS);
    67	            page.setDefaultTimeout(SELECTOR_TIMEOUT_MS);
    68	            page.waitForSelector(STATUS_SELECTOR);
    69	
    70	            // 5) 최종 렌더링된 HTML 문자열 추출
    71	            log.debug("페이지 HTML 로드");
    72	            String renderedHtml = page.content();
    73	
    74	            // 6) Jsoup으로 파싱
    75	            log.debug("HTML 파싱 시작");
    76	            String statusText = parseStatusFromHtml(renderedHtml, trackingNumber);
    77	            log.info("배송 상태 파싱 완료: 운송장={}, 상태={}", trackingNumber, statusText);
    78	
    79	            return statusText;
    80	
    81	        } catch (Exception e) {
