   134	                        "배송 정보가 없습니다. 운송장 번호를 확인해주세요: " + trackingNumber
   135	                );
   136	            }
   137	
   138	            // 마지막 행(최신 상태)의 5번째 컬럼 선택
   139	            String statusText = rows.last().select("td").get(4).text().trim();
   140	
   141	            if (statusText.isEmpty()) {
   142	                log.warn("배송 상태 텍스트가 비어 있음: 운송장={}", trackingNumber);
   143	                throw new ShipmentException(
   144	                        ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   145	                        "배송 상태 정보를 찾을 수 없습니다."
   146	                );
   147	            }
   148	
   149	            return statusText;
   150	
   151	        } catch (IndexOutOfBoundsException e) {
   152	            log.error("HTML 파싱 중 인덱스 오류: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
   153	            throw new ShipmentException(
   154	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   155	                    "배송 상태 정보 파싱 실패: 예상한 형식과 다릅니다.",
   156	                    e
   157	            );
   158	        } catch (Exception e) {
   159	            if (e instanceof ShipmentException) {
   160	                throw (ShipmentException) e;
   161	            }
   162	
   163	            log.error("HTML 파싱 중 오류 발생: 운송장={}, 오류={}", trackingNumber, e.getMessage(), e);
   164	            throw new ShipmentException(
   165	                    ShipmentErrorCode.TRACKING_HTML_PARSE_ERROR,
   166	                    "배송 상태 정보 파싱 실패: " + e.getMessage(),
   167	                    e
